import type { Answer, Topic } from "./types";

/**
 * One-click demo profiles. Their placement answers are generated by a simple
 * age rule (plus a few fixed overrides), so they are clearly fake and are
 * labeled "Sample data" everywhere they appear in the UI.
 */
export interface SampleProfile {
  id: string;
  label: string;
  childName: string;
  age: number;
  targetId: string;
  targetName: string;
  blurb: string;
  /** Rule: "yes" when a topic's starting age is below this, otherwise "not yet". */
  yesBelowStartAge: number;
  overrides: Record<string, Answer>;
}

export const SAMPLE_PROFILES: SampleProfile[] = [
  {
    id: "charlie",
    label: "Kindergartner (Charlie)",
    childName: "Charlie",
    age: 5,
    targetId: "mt_mr_Vk7FGzK",
    targetName: "Adding and subtracting",
    blurb: "Age 5 · goal: Adding and subtracting (Mathematics)",
    yesBelowStartAge: 5,
    overrides: {
      // "Number bonds" — answered "not sure" for variety in the sample data.
      mt_s2mfRBoTal: "not_sure",
    },
  },
  {
    id: "lillian",
    label: "5th grader (Lillian)",
    childName: "Lillian",
    age: 10,
    targetId: "mt_14T5yPXUq_",
    targetName: "Adding Fractions (Unlike Denominators)",
    blurb: "Age 10 · goal: Adding Fractions (Unlike Denominators)",
    yesBelowStartAge: 9,
    overrides: {
      // "Equivalent fractions (age 9+)" — answered "not sure" in the sample.
      "mt_ebPelt-qAl": "not_sure",
    },
  },
];

export function sampleAnswer(profile: SampleProfile, topic: Topic): Answer {
  const override = profile.overrides[topic.id];
  if (override) return override;
  return topic.ageRangeStart < profile.yesBelowStartAge ? "yes" : "not_yet";
}
